select productos.nombre, caategorias.caategoria_id, caategorias.nombre from productos inner join caategorias on productos.caategoria_id = caategorias.id order by productos.nombre asc; /*inner join fusiona la tabla pra mostrar los productos con el nombre de su categoria y order. by ____ asc lo ordena ascendentemente*/ 
select * from productos where stock = true; /*muestra los poreductos con un estock existente por el where y por el bollean stock*/
select caategoria_id avg(precio) as precio_promedio from productos group by caategoria_id; /*muestra el recio promedio pro avg y group by, los agrupa*/
select pedidos.pedido_id, clientes.pedido_id, clientes.nombre, pedidos.fecha, pedidos.estados from pedidos inner join clientes on clientes.pedido_id = pedidos.pedido_id where clientes.nombre = 'Juan Perez'; /*fusiona el cleinte con la fecha, pero, por la condicion, solo se elije un nombre, en este caso: "Juan Perez"*/
select pedido_id, sum(precio_unitario * cantidad) as precio_total from detalle_pedido group by pedido_id; /* multiplicamos el precio unitario por la cantidad y sum nos devuelve la cantidad y group by da una condicione que solo con los que tenga un ide del cliente, seala suma y eso se repite con cada grupo*/
select cliente_id, count(*) from pedidos group by cliente_id having count(*) > 1; /*con counto contamostmos todas las filas registradas y group by agrupa a todos los pedidos que tengan ese ide y con having condicionamos a que tenga un valor mayor a 1*/
delete from clientes where not exists(select 1 from pedidos where pedidos.cliente_id = clientes.cliente_id); /*eliminara a todos los clientes que no exista igualdad entre pediods y clientes